  sec(head("Direitos e governança", "O que você pode <strong>esperar de nós</strong>") + PROSE(DRAFT_NOTE + checks(["Ser informado quando uma decisão for apoiada por IA e solicitar revisão humana.", "Exercer todos os direitos da LGPD pelo <a href='/canal-lgpd/'>Canal LGPD</a>, inclusive sobre dados biométricos.", "Contestar resultados (ex.: falha de reconhecimento facial) com atendimento humano e alternativa de autenticação.", "Governança pelo Comitê de Proteção de Dados e pelo Comitê de Segurança e Qualidade, com avaliação de riscos antes de cada lançamento e monitoramento contínuo em produção.", "Conformidade com a LGPD, com as normas da ANS e do CFM (telemedicina) e com as boas práticas internacionais de IA confiável; acompanhamento do marco legal brasileiro de IA."]) + '<p class="trix-note">Dúvidas ou relatos sobre uso de IA: <a href="mailto:dpo@trixti.com.br">dpo@trixti.com.br</a> · <a href="/canal-de-compliance/">Canal de Compliance</a>.</p>')),
